export function buildErpSalePayload(transaction: Transaction): Transaction & {
    transaction_date: string;
    currency_code: string;
    exchange_rate?: number;
    customer_ref?: string;
    customer_code?: string;
    customer?: ReturnType<typeof customerNumberIdentity>;
    original_source_transaction_id?: string;
    original_source_display_id?: string;
} {
    const base = sanitizeTransactionForErp(normalizeTransactionForSync(coerceTransactionItemsForErp(transaction)));
    const isFiscalDisabled = base.fiscalMode === 'NONE';
    const fiscalFields = isFiscalDisabled
        ? {
              ncf: undefined,
              ncfType: undefined,
              legacyNcf: undefined,
              electronicNcf: undefined,
              fiscalProvider: 'NONE' as const,
          }
        : {};
    const isCreditNote = !isFiscalDisabled && (base.documentType === 'REFUND' || base.ncfType === 'B04' || base.ncfType === 'E34');
    const customerIdentity = customerNumberIdentity(base.customerSnapshot);
    return {
        ...base,
        ...fiscalFields,
        transaction_date: base.date,
        currency_code: pickTransactionCurrency(base),
        exchange_rate: pickTransactionExchangeRate(base),
        customer_ref: base.customerId || undefined,
        ...(customerIdentity.customer_code ? {
            customer_code: customerIdentity.customer_code,
            customer: { ...(base as Transaction & { customer?: Record<string, unknown> }).customer, ...customerIdentity },
        } : {}),
        ...(isCreditNote
            ? {
                  original_source_transaction_id: base.original_transaction_id,
                  original_source_display_id: base.original_display_id,
              }
            : {}),
    };
}

/** Credit notes share the same payload shape as sales (NC id = source_credit_note_id on the transaction). */
export function buildErpCreditNotePayload(transaction: Transaction): ReturnType<typeof buildErpSalePayload> {
    return buildErpSalePayload(transaction);
}

import { BusinessConfig, PaymentEntry, Transaction } from '../types';
import { paymentEntryIsCxCCredit } from './creditRules';

const roundToTwo = (value: number): number => Math.round((value + Number.EPSILON) * 100) / 100;

const toNumber = (value: unknown): number => {
    const numeric = Number(value);
    return Number.isFinite(numeric) ? numeric : 0;
};

const normalizeCurrencyCode = (value: unknown, fallback: string): string => {
    if (typeof value !== 'string') return fallback;
    const normalized = value.trim().toUpperCase();
    return normalized || fallback;
};

const getPaymentCurrencyCode = (payment: Partial<PaymentEntry>, baseCurrencyCode: string): string => {
    return normalizeCurrencyCode(payment.currencyCode ?? payment.currency_code, baseCurrencyCode);
};

const getPaymentExchangeRate = (payment: Partial<PaymentEntry>, baseCurrencyCode: string): number => {
    const currencyCode = getPaymentCurrencyCode(payment, baseCurrencyCode);
    const directRate = toNumber(payment.exchangeRate ?? payment.exchange_rate);
    if (directRate > 0) return directRate;

    const amountOriginal = toNumber(payment.amountOriginal);
    const amountBase = roundToTwo(toNumber(payment.amount));
    if (currencyCode !== baseCurrencyCode && amountOriginal > 0 && amountBase > 0) {
        return roundToTwo(amountBase / amountOriginal);
    }

    return 1;
};

export const getPaymentAppliedBaseAmount = (payment: Partial<PaymentEntry>): number => {
    const preferred = payment.appliedAmount ?? payment.applied_amount ?? payment.amountApplied;
    if (preferred !== undefined && preferred !== null) {
        return roundToTwo(toNumber(preferred));
    }
    return roundToTwo(toNumber(payment.amount));
};

export const getPaymentChangeBaseAmount = (payment: Partial<PaymentEntry>): number => {
    const preferred = payment.changeAmount ?? payment.change_amount;
    if (preferred !== undefined && preferred !== null) {
        return roundToTwo(toNumber(preferred));
    }
    const amount = roundToTwo(toNumber(payment.amount));
    const applied = getPaymentAppliedBaseAmount(payment);
    return roundToTwo(Math.max(0, amount - applied));
};

export const getPaymentOriginalAmount = (payment: Partial<PaymentEntry>, baseCurrencyCode: string): number => {
    const direct = toNumber(payment.amountOriginal);
    if (direct > 0) return roundToTwo(direct);

    const amount = roundToTwo(toNumber(payment.amount));
    const currencyCode = getPaymentCurrencyCode(payment, baseCurrencyCode);
    const exchangeRate = getPaymentExchangeRate(payment, baseCurrencyCode);
    if (currencyCode !== baseCurrencyCode && exchangeRate > 0) {
        return roundToTwo(amount / exchangeRate);
    }

    return amount;
};

export const getPaymentReceivedAmountForDrawer = (payment: Partial<PaymentEntry>, baseCurrencyCode: string): number => {
    const currencyCode = getPaymentCurrencyCode(payment, baseCurrencyCode);
    if (currencyCode === baseCurrencyCode) {
        return roundToTwo(toNumber(payment.amount));
    }
    return getPaymentOriginalAmount(payment, baseCurrencyCode);
};

 * applied to the ticket, not the amount tendered before change. Deferred credit is
 * still included because it is a valid way in which the ticket was settled.
 */
export const buildZReportPaymentMethodSummary = (
  transactions: Transaction[],
  config?: BusinessConfig,
): ZReportPaymentMethodLine[] => {
  const buckets = new Map<string, ZReportPaymentMethodLine>();

  for (const transaction of transactions || []) {
    if (transaction.documentType === 'VOID') continue;
    const isRefund = transaction.documentType === 'REFUND' || transaction.ncfType === 'B04';
    for (const payment of transaction.payments || []) {
      if (!payment) continue;
      const configured = resolveConfiguredMethod(payment, config);
      const methodType = resolvePaymentMethodTypeForRuntime(payment.method, payment.methodLabel, payment.methodId);
      const methodId = normalize(payment.methodId || configured?.id) || undefined;
      const name = resolveZReportPaymentMethodName(payment, config);
      const isPending = paymentEntryIsCxCCredit(payment);
      const baseAmount = isPending ? Number(payment.amount || 0) : getPaymentAppliedBaseAmount(payment);
      const amount = isRefund ? -Math.abs(baseAmount) : baseAmount;
      const key = methodId ? `id:${methodId.toLowerCase()}` : `label:${name.toLowerCase()}:${methodType}`;
      const current = buckets.get(key);
      buckets.set(key, {
        methodId,
        methodType,
        name,
        amount: roundMoney((current?.amount || 0) + amount),
        isPending,
      });
    }
  }

  return [...buckets.values()].filter(line => Math.abs(line.amount) > 0.0001);

const resolveConfiguredMethod = (payment: Partial<PaymentEntry>, config?: BusinessConfig) => {
  const methods = config?.paymentMethods || [];
  const methodId = normalize(payment.methodId);
  if (methodId) {
    const byId = methods.find(method => normalize(method.id).toLowerCase() === methodId.toLowerCase());
    if (byId) return byId;
  }
  const label = normalize(payment.methodLabel);
  if (label) {
    const byName = methods.find(method => normalize(method.name).toLowerCase() === label.toLowerCase());
    if (byName) return byName;
  }
  const runtimeType = resolvePaymentMethodTypeForRuntime(payment.method, payment.methodLabel, payment.methodId);
  const sameType = methods.filter(method => method.type === runtimeType && method.isEnabled !== false);
  return sameType.length === 1 ? sameType[0] : undefined;
};

export const resolveZReportPaymentMethodName = (
  payment: Partial<PaymentEntry>,
  config?: BusinessConfig,
): string => {
  const configured = resolveConfiguredMethod(payment, config);
  if (configured?.name) return configured.name;
  const explicitLabel = normalize(payment.methodLabel);
  if (explicitLabel && explicitLabel.toUpperCase() !== normalize(payment.method).toUpperCase()) return explicitLabel;
  const runtimeType = resolvePaymentMethodTypeForRuntime(payment.method, payment.methodLabel, payment.methodId);
  return DEFAULT_METHOD_LABELS[runtimeType] || DEFAULT_METHOD_LABELS[normalize(payment.method).toUpperCase()] || explicitLabel || 'Otro';

