export const calculateZReportStats = (transactions: Transaction[], collections: Collection[] = []): ZReportStats => {
    if ((!transactions || transactions.length === 0) && (!collections || collections.length === 0)) {
        return {
            averageTicket: 0,
            itemsPerSale: 0,
            peakHour: 'N/A',
            topProduct: null,
            returnsCount: 0,
            returnsTotal: 0,
            grossSales: 0,
            netSales: 0,
            discountsTotal: 0,
            advancementsTotal: 0,
            collectionsTotal: 0
        };
    }

